def group_advantage(reward: float, mean_r: float, std_r: float, eps: float = 1e-4) -> float:
    return round((reward - mean_r) / (std_r + eps), 4)

def group_advantages(rewards: list, eps: float = 1e-4) -> list:
    """Normalize every reward in the group against the group's own mean/std."""
    n = len(rewards)
    mean_r = sum(rewards) / n
    var_r = sum((r - mean_r) ** 2 for r in rewards) / n
    std_r = var_r ** 0.5
    return [group_advantage(r, mean_r, std_r, eps) for r in rewards]

print(group_advantages([0.9, 0.6, 0.3, 0.1]))
